scwin.vScrenID = 'ULDMGT80205.gfm';
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.getYYYYMMDD = function() {
    var now = new Date();
    var month = (now.getMonth() + 1) + "";
    var day = now.getDate() + "";
    if (day.length == 1) day = "0" + day;
    if (month.length == 1) month = "0" + month;
    return now.getYear() + "" + month + "" + day;
};
scwin.fn_list_sync = function() {

	//----W-Craft WebSquare 변환 확인: ClearData----//
    MxDataSet.ClearData();

	//----W-Craft WebSquare 변환 확인: ClearData----//
    dSetDisp.ClearData();
    var vHttp = "";
    vHttp = in_rcv_rul;
    var url = vHttp + "/rcv/extractCheck.jsp?startDate=" + txb_date1.getValue() + "&endDate=" + txb_date2.getValue() + "&formCd=" + txb_form_cd.getValue() + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    MxDataSet.DataID = url;

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet.reset();
    $c.cm.ShowWin(MxGrid_1);
};
scwin.checkDataSetValue = function() {
    for (var i = 1; i <= MxDataSet.CountRow; i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************


	//----W-Craft WebSquare 변환 확인: ColumnString----//

	//----W-Craft WebSquare 변환 확인: AddRow----//
        dSetDisp.AddRow(); /*ORG SRC: dSetDisp.NameValue(dSetDisp.CountRow, "ACPT_NO") = MxDataSet.ColumnString(i, 1);*/ X = MxDataSet.ColumnString(i, 1); /*ORG SRC: dSetDisp.NameValue(dSetDisp.CountRow, "EXTRACT_RESULT") = MxDataSet.ColumnString(i, 2);*/ X = MxDataSet.ColumnString(i, 2);
    }
};
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    scwin.checkDataSetValue();
    textbox_1.setValue("총 " + rowcount + "건");
    $c.cm.CloseWin(rowcount, MxGrid_1);
};
scwin.gform_onload = function() {
    dSetDisp.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=extract_now_monitoring";

	//----W-Craft WebSquare 변환 확인: reset----//
    dSetDisp.reset();
    MxDataSet.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=extract_now_monitoring";

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet.reset();
    $c.libRoundPanel.PanelToGroupBox_01(panel_1);
    //PanelToGroupBox_02(panel_2);
    txb_date1.setValue(scwin.getYYYYMMDD());
    txb_date2.setValue(scwin.getYYYYMMDD());
};
scwin.btn_cal1_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: popUpCalendar----//
    popUpCalendar(txb_date_bg1, 'txb_date1', 'yyyymmdd'); //alert('image_2.onclick');

};
scwin.btn_cal2_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: popUpCalendar----//
    popUpCalendar(txb_date_bg2, 'txb_date2', 'yyyymmdd'); //alert('image_2.onclick');

};
scwin.btn_sys_search_onclick = function(e) {
    if (txb_date1.getValue() != "" && txb_date2.getValue() != "") {
        scwin.fn_list_sync(); //alert();

    } else {
        alert("접수일자를 지정하십시요");
    }
};
